cd /work/workspace/deliverable && python3 - <<'EOF'
import json
data = json.load(open('achados.json'))
assert isinstance(data, list), "root must be list"
ok_efeito = {"anuencia","preco","indenizacao","prazo","nenhum"}
keys = {"achado","onde","por_que_importa","efeito","solucao"}
problems = []
for i, f in enumerate(data, 1):
    missing = keys - set(f)
    extra = set(f) - keys
    if missing: problems.append((i, "faltam", sorted(missing)))
    if extra: problems.append((i, "extras", sorted(extra)))
    if f.get("efeito") not in ok_efeito: problems.append((i, "efeito invalido", f.get("efeito")))
    for k in keys - {"efeito"}:
        v = f.get(k)
        if not isinstance(v, str) or not v.strip(): problems.append((i, "vazio/" + k, repr(v)[:40]))
print("findings:", len(data))
from collections import Counter
print("efeitos:", dict(Counter(f["efeito"] for f in data)))
print("problemas:", problems if problems else "nenhum")
EOF

